from collections import deque
from typing import List

def minMoves(maze: List[List[int]], x: int, y: int) -> int:
    n, m = len(maze), len(maze[0])
    if maze[0][0] == 1 or maze[x][y] == 1:
        return -1
    coin = {}
    for i in range(n):
        for j in range(m):
            if maze[i][j] == 2:
                coin[(i, j)] = len(coin)
    full = (1 << len(coin)) - 1
    start = 1 << coin[(0, 0)] if (0, 0) in coin else 0   # 起点本身可能有金币
    seen = {(0, 0, start)}
    dq = deque([(0, 0, start, 0)])
    while dq:
        r, c, mask, d = dq.popleft()
        if (r, c) == (x, y) and mask == full:
            return d
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < n and 0 <= nc < m and maze[nr][nc] != 1:
                nm = mask | (1 << coin[(nr, nc)]) if (nr, nc) in coin else mask
                if (nr, nc, nm) not in seen:
                    seen.add((nr, nc, nm))
                    dq.append((nr, nc, nm, d + 1))
    return -1
